def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    def spans(length, separators):
        out, start = [], 0
        for p in separators + [length]:
            if start < p:
                out.append((start, p))
            start = p + 1
        return out

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    separator_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}

    panels = []
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
