                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != background and grid[r][c] not in separator_colors}
            panels.append((ri, ci, r0, r1, c0, c1, marks))

    source = max(panels, key=lambda panel: len(panel[6]))
    sri, sci, sr0, sr1, sc0, sc1, motif = source
